-- Private Storage bucket for verification documents (government ID
-- photos, ownership/authorization paperwork). NEVER the same bucket as
-- the public property-images bucket from Milestone 3. public = false, so
-- objects are only reachable via a signed URL generated by trusted
-- server code that has independently checked the requester is the
-- applicant or a moderator/admin (see app/dashboard/verification/actions.ts).

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'verification-documents', 'verification-documents', false, 10485760,
  array['image/jpeg', 'image/png', 'application/pdf']
)
on conflict (id) do nothing;

-- Even direct storage.objects access (bypassing our app entirely) is
-- scoped to the uploader or moderation roles — defense in depth beyond
-- "we only generate signed URLs for authorized requests."
create policy verification_documents_bucket_read on storage.objects
  for select
  to authenticated
  using (
    bucket_id = 'verification-documents'
    and (
      owner = auth.uid()
      or public.has_role('admin') or public.has_role('moderator')
    )
  );

create policy verification_documents_bucket_write on storage.objects
  for insert
  to authenticated
  with check (bucket_id = 'verification-documents' and owner = auth.uid());

create policy verification_documents_bucket_delete on storage.objects
  for delete
  to authenticated
  using (bucket_id = 'verification-documents' and owner = auth.uid());
